def _numeros_lies():
    """ruche-0022: the account numbers the real registry binds in gouvernance/, so that fixtures copied from it agree."""
    lies = {}
    for fichier in sorted((RACINE / "gouvernance").glob("*.yaml")):
        donnees = yaml.safe_load(fichier.read_text(encoding="utf-8")) or {}
        for liste in (donnees.values() if isinstance(donnees, dict) else []):
            for entree in (liste if isinstance(liste, list) else []):
                nom = isinstance(entree, dict) and (entree.get("pseudo") or entree.get("account"))
                if nom and type(entree.get("github_id")) is int:
                    lies[str(nom).casefold()] = entree["github_id"]
    return lies


NUMEROS_LIES = _numeros_lies()


def numero_de(login):
    """ruche-0022: the GitHub account number the tests give a login (the same in faux_gh), as the API would: the real
    registry's binding if it has one, else a number derived from the login."""
    return NUMEROS_LIES.get(str(login).casefold()) or zlib.crc32(str(login).casefold().encode()) % 10 ** 8 + 1


def valeur_option(arguments, option):
    return next((a.split("=", 1)[1] if "=" in a else arguments[i + 1] for i, a in enumerate(arguments)
                 if (a == option and i + 1 < len(arguments)) or a.startswith(option + "=")), None)


def lancer(*arguments):
    arguments = list(arguments)
    # ruche-0022: like the workflows, which read the PR author's number from the API, each login has its number (numero_de) for
    # bee inscrire and bee verifier-pr, unless the test gives one (--github-id) or none (--github-id=).
    for commande, option in (("inscrire", "--pseudo"), ("verifier-pr", "--auteur")):
        if commande in arguments and valeur_option(arguments, "--github-id") is None and valeur_option(arguments, option) is not None:
            arguments += ["--github-id", str(numero_de(valeur_option(arguments, option)))]
    arguments = [a for a in arguments if a != "--github-id="]
    sortie, erreur = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(sortie), contextlib.redirect_stderr(erreur):
        code = bee.principal(arguments)
    return code, sortie.getvalue() + erreur.getvalue()


def git(depot, *arguments):
    return subprocess.run(["git", "-C", str(depot), *arguments], check=True, capture_output=True, text=True).stdout


# ruche-0090: the only tests that may read the live registry's data (its self-service folders). validation.yml runs exactly
# these on a data-only PR, and skips the rest of the suite (TestCiScope checks the workflow against this list).
TESTS_REGISTRE_REEL = ("TestRegistreReel", "TestRegistre.test_le_registre_livre_est_valide",
                       "TestArbre.test_chemins_livres_tiennent_dans_un_budget_court")
DOSSIERS_REELS = tuple(os.path.join(str(RACINE), d) + os.sep for d in DONNEES_REGISTRE)


def chemins_lus(evenement, arguments):
    """Absolute paths an audit event reads: an opened or listed path; for a subprocess, its working directory and its
    arguments as paths (relative ones from that directory, after git's -C). None when the event cannot be resolved."""
    if evenement == "subprocess.Popen":
        _, argv, cwd, _ = arguments
        argv = [argv] if isinstance(argv, (str, bytes, os.PathLike)) else list(argv or ())
        ici = os.path.join(os.getcwd(), os.fsdecode(cwd)) if cwd is not None else os.getcwd()
        chemins, mots = [ici], iter([os.fsdecode(a) for a in argv[1:] if isinstance(a, (str, bytes, os.PathLike))])
        est_git = bool(argv) and os.path.basename(os.fsdecode(argv[0])) == "git"
        for mot in mots:
            if mot == "-C" and est_git:
                ici = os.path.join(ici, next(mots, ""))
                chemins.append(ici)
            elif not mot.startswith("-"):
                chemins.append(os.path.join(ici, mot))
        return [os.path.normpath(c) for c in chemins]
    if evenement not in ("open", "os.scandir", "os.listdir") or not arguments:
        return None
    chemin = os.fsdecode(arguments[0])
    if evenement == "open" and arguments[1:2] == (None,) and not os.path.isabs(chemin) and os.sep not in chemin:
        return None  # os.open of a bare name: maybe relative to a dir_fd the event does not give (shutil.rmtree)
    return [os.path.normpath(chemin if os.path.isabs(chemin) else os.path.join(os.getcwd(), chemin))]


def garde_donnees_reelles(evenement, arguments):
    """Audit hook, installed once below: a test outside TESTS_REGISTRE_REEL that opens or lists a path in the live
    registry's data folders, or starts a subprocess there or naming such a path, fails, however the path was built (bee
    run without --registre, an alias of RACINE, rglob, a copy, cat, git -C). Not seen: a read outside a test's frames
    (setUpClass, import time, another thread), through a symlink to the repository, by a bare stat (exists, is_file) or
    a bare-named os.open, or by a subprocess that does not name the path (a shell script's text, bee run from the
    repository without --registre, an environment variable)."""
    if evenement not in ("open", "os.scandir", "os.listdir", "subprocess.Popen"):
        return
    try:
        chemins = chemins_lus(evenement, arguments) or ()
    except (TypeError, ValueError, OSError):  # a file descriptor, None, a deleted working directory
        return
    chemin = next((c for c in chemins if (c + os.sep).startswith(DOSSIERS_REELS)), None)
    if chemin is None:
        return
    cadre = sys._getframe(1)
    while cadre is not None and not isinstance(cadre.f_locals.get("self"), unittest.TestCase):
        cadre = cadre.f_back
    if cadre is None:
        return  # outside a test (test discovery, another thread)
    test = cadre.f_locals["self"]
    permis = {(globals().get(c), m) for c, _, m in (n.partition(".") for n in TESTS_REGISTRE_REEL)}
    if (type(test), "") in permis or (type(test), test._testMethodName) in permis:
        return
    lectures = test.__dict__.setdefault("_lectures_reelles", [])
    if not lectures:
        test.addCleanup(lambda: test.fail(f"reads the live registry's data ({', '.join(lectures[:3])}): only TESTS_REGISTRE_REEL "
                                          "may, the tests validation.yml still runs on a data-only PR; use the frozen fixture"))
    lectures.append(os.path.relpath(chemin, RACINE))


sys.addaudithook(garde_donnees_reelles)


class TestRegistreReel(unittest.TestCase):
    """ruche-0093 : les commandes de lecture tiennent sur le registre réel, tel qu'il est (les autres tests lisent le jeu figé)."""

    def test_les_commandes_de_lecture_tiennent_sur_le_registre_reel(self):
        with tempfile.TemporaryDirectory() as sortie:
            for arguments in (("site", "--sortie", sortie), ("cap", "--json"), ("essaim", "--json"),
                              ("classement", "--json"), ("lister", "--json"), ("niveaux",), ("debats",)):
                with self.subTest(commande=arguments[0]):
                    code, texte = lancer("--registre", str(RACINE), *arguments)
                    self.assertEqual(code, 0, texte)


class TestJeuFige(unittest.TestCase):
    """ruche-0093 : le jeu figé n'est que des données YAML, et rien hors des tests ne l'importe ni ne l'exécute."""

    def test_que_des_donnees_yaml(self):
        dossier = RACINE / "outils" / "tests"
        intrus = sorted(p.relative_to(RACINE).as_posix() for p in dossier.rglob("*")
                        if "__pycache__" not in p.parts and (p.is_symlink() or (p.is_file() and p.suffix != ".yaml")))
        self.assertEqual(intrus, [])

    def test_rien_ne_l_importe_ni_ne_l_execute(self):
        codes = [RACINE / "outils" / n for n in ("bee.py", "site_bee.py", "inventaire_marqueurs.py")]
        codes += [p for p in (RACINE / "outils" / "juge").rglob("*.py") if not p.name.startswith("test_")]
        codes += list((RACINE / "outils" / "repetition").rglob("*")) + list((RACINE / ".github").rglob("*.yml"))
        for chemin in sorted(c for c in codes if c.is_file() and "__pycache__" not in c.parts):
            with self.subTest(fichier=chemin.relative_to(RACINE).as_posix()):
                self.assertNotRegex(chemin.read_text(encoding="utf-8", errors="replace"),
                                    r"outils[/.]tests|\bfrom tests\b|\bimport tests\b|tests/registre")


class TestWorkflows(unittest.TestCase):
    """Un workflow illisible ne tourne pas du tout, sans prévenir : chaque fichier doit être du YAML valide."""

    def test_workflows_lisibles(self):
        import yaml
        dossier = pathlib.Path(__file__).resolve().parent.parent / ".github" / "workflows"
        fichiers = sorted(dossier.glob("*.yml"))
        self.assertTrue(fichiers)
        for f in fichiers:
            with self.subTest(workflow=f.name):
                donnees = yaml.safe_load(f.read_text(encoding="utf-8"))
                self.assertIsInstance(donnees, dict)
                self.assertIn("jobs", donnees)


class TestFusionAutoNeMergeQuApresVerification(unittest.TestCase):
    """fusion-auto.yml: the merge step runs only after the verification step ran, succeeded and returned code 0, for a PR
    it found; a skipped verification (no PR found) never leads to `gh pr merge` (its absent output, null, equals '0')."""

    def test_la_fusion_exige_une_verification_reussie(self):
        import yaml
        flux = yaml.safe_load((RACINE / ".github" / "workflows" / "fusion-auto.yml").read_text(encoding="utf-8"))
        etapes = [e for job in flux["jobs"].values() for e in job.get("steps", [])]
        fusion = [e for e in etapes if re.search(r"(?m)^\s*gh pr merge ", e.get("run", ""))]
        self.assertEqual(len(fusion), 1)
        condition = " ".join(str(fusion[0].get("if", "")).split())
        self.assertEqual(condition.split(" && "), ["steps.verif.outcome == 'success'", "steps.verif.outputs.code != ''",
                                                   "steps.verif.outputs.code == '0'", "steps.pr.outputs.numero != ''"])
        for interdit in ("||", "!(", "${{"):
            self.assertNotIn(interdit, condition)
        self.assertEqual(len(re.findall(r"(?m)^\s*gh pr merge ", "\n".join(e.get("run", "") for e in etapes))), 1)
        self.assertNotRegex("\n".join(e.get("run", "") for e in etapes), r"pulls/[^ ]*/merge", "no other way to merge")
        self.assertIn('[[ "$NUMERO" =~ ^[0-9]+$ ]] ||', fusion[0]["run"])
        self.assertLess(fusion[0]["run"].index("=~ ^[0-9]+$"), fusion[0]["run"].index("gh pr merge"))


class TestCiScope(unittest.TestCase):
    """ruche-0090: a registry PR that only adds or modifies self-service data files skips the tool and judge test suites
    (bee ci-scope, decided by the base's tool in validation.yml); anything else runs the full suite (fails closed)."""

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.depot = pathlib.Path(self.temp.name) / "depot"
        self.depot.mkdir()
        git(self.depot, "init", "-q", "-b", "main")
        self.ecrire("outils/bee.py", (RACINE / "outils" / "bee.py").read_text(encoding="utf-8"))
        self.ecrire("taches/miniz/miniz-0001.yaml")
        self.ecrire("README.md")
        self.base = self.commit()

    def tearDown(self):
        self.temp.cleanup()

    def ecrire(self, chemin, texte="id: x\n"):
        fichier = self.depot / chemin
        fichier.parent.mkdir(parents=True, exist_ok=True)
        fichier.write_text(texte, encoding="utf-8")

    def commit(self):
        git(self.depot, "add", "-A")
        git(self.depot, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "c", "--allow-empty")
        return git(self.depot, "rev-parse", "HEAD").strip()

    def portee(self):
        return bee.ci_scope(self.depot, self.base, self.commit())

    def test_data_only(self):
        for chemin in ("membres/alice.yaml", "taches/miniz/miniz-0001.yaml", "taches/miniz/miniz-0002.yaml",
                       "contributions/miniz/miniz-0001-c1.yaml", "votes/miniz-0001-c1/bruno.yaml", "votes/P-0001/bruno.yaml",
                       "mesures/miniz-0001-c1/chloe.yaml", "propositions/P-0001.yaml", "debats/D-0001.yaml",
                       "invitations/I-0001.yaml", "invitations/ne-plus-contacter.yaml"):
            self.ecrire(chemin, "id: y\n")
        self.assertEqual(self.portee(), ("data", None))
        self.assertEqual(lancer("--registre", str(self.depot), "ci-scope", "--base", self.base), (0, "data\n"))

    def test_anything_else_runs_the_full_suite(self):
        lien = lambda chemin: os.symlink("../README.md", self.depot / chemin)  # noqa: E731
        sha = git(self.depot, "rev-parse", "HEAD").strip()
        cas = {
            "code": lambda: self.ecrire("outils/bee.py", "print('data')\n"),
            "workflow": lambda: self.ecrire(".github/workflows/x.yml"),
            "root file": lambda: self.ecrire("README.md", "y\n"),
            "frozen fixture": lambda: self.ecrire("outils/tests/registre/taches/miniz/miniz-0001.yaml"),
            "unknown top-level folder": lambda: self.ecrire("Taches/miniz/miniz-0001.yaml"),
            "data and code": lambda: (self.ecrire("membres/alice.yaml"), self.ecrire("bee.yaml")),
            "deletion": lambda: git(self.depot, "rm", "-q", "taches/miniz/miniz-0001.yaml"),
            "rename": lambda: git(self.depot, "mv", "taches/miniz/miniz-0001.yaml", "taches/miniz/miniz-0002.yaml"),
            "mode change": lambda: (self.depot / "taches/miniz/miniz-0001.yaml").chmod(0o755),
            "executable added": lambda: (self.ecrire("membres/alice.yaml"), (self.depot / "membres/alice.yaml").chmod(0o755)),
            "symlink": lambda: ((self.depot / "membres").mkdir(), lien("membres/alice.yaml")),
            "typechange": lambda: ((self.depot / "taches/miniz/miniz-0001.yaml").unlink(), lien("taches/miniz/miniz-0001.yaml")),
            "gitlink": lambda: git(self.depot, "update-index", "--add", "--cacheinfo", f"160000,{sha},membres/alice.yaml"),
            "other extension": lambda: self.ecrire("taches/miniz/notes.txt"),
            "subfolder": lambda: self.ecrire("membres/sous/alice.yaml"),
            "suffix": lambda: self.ecrire("debats/D-0001.yaml.py"),
            "newline in the name": lambda: self.ecrire("membres/alice.yaml\n"),
            "not UTF-8": lambda: self.ecrire(os.fsdecode(b"membres/\xff.yaml")),
            "no change": lambda: None,
        }
        for nom, changer in cas.items():
            with self.subTest(cas=nom):
                git(self.depot, "reset", "-q", "--hard", self.base)
                git(self.depot, "clean", "-qfdx")
                changer()
                if nom != "gitlink":
                    git(self.depot, "add", "-A")
                git(self.depot, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "c", "--allow-empty")
                portee, raison = bee.ci_scope(self.depot, self.base, "HEAD")
                self.assertEqual(portee, "full")
                self.assertTrue(raison)
        self.assertEqual(bee.ci_scope(self.depot, "0" * 40, "HEAD")[0], "full", "unknown base")
        self.assertEqual(bee.ci_scope(self.temp.name, self.base, "HEAD")[0], "full", "not a repository")
        code, sortie = lancer("--registre", str(self.depot), "ci-scope", "--base", "0" * 40)
        self.assertEqual((code, sortie.splitlines()[0]), (0, "full"))

    @staticmethod
    def etapes():
        """validation.yml's steps, and those this test names by role (a renamed step fails here: follow it)."""
        etapes = yaml.safe_load((RACINE / ".github/workflows/validation.yml").read_text(encoding="utf-8"))["jobs"]["valider"]["steps"]
        nom = lambda debut: next(s for s in etapes if s.get("name", "").startswith(debut))  # noqa: E731
        return etapes, {"portee": nom("Scope of the PR"), "outil": nom("Tests de l'outil"), "juge": nom("Tests unitaires du juge"),
                        "reel": nom("Tests that read the live registry"), "valider": nom("Validation complète"),
                        "regles": nom("Règles de la pull request")}

    def rejouer(self, script, env, cwd=None):
        """Runs a step's script as Actions does by default (bash -e), with this interpreter as python3 and a stub gh that
        logs its arguments and prints $FAUX_GH (fails if it is « error »)."""
        dossier = pathlib.Path(tempfile.mkdtemp(dir=self.temp.name))
        (dossier / "bin").mkdir()
        (dossier / "bin/python3").write_text(f'#!/bin/sh\nexec "{sys.executable}" "$@"\n', encoding="utf-8")
        (dossier / "bin/gh").write_text('#!/bin/sh\necho "$@" >> "$RUNNER_TEMP/gh.log"\n[ "$FAUX_GH" != error ] || exit 1\n'
                                        'echo "$FAUX_GH"\n', encoding="utf-8")
        for f in (dossier / "bin").iterdir():
            f.chmod(0o755)
        (dossier / "etape.sh").write_text(script, encoding="utf-8")
        tout = {k: v for k, v in os.environ.items() if k != "BEE_REGISTRE"}
        tout.update(PATH=f"{dossier / 'bin'}{os.pathsep}{os.environ['PATH']}", RUNNER_TEMP=str(dossier),
                    GITHUB_OUTPUT=str(dossier / "sortie"), GITHUB_REPOSITORY="Bee-ruche/registre", GH_TOKEN="x", **env)
        r = subprocess.run(["bash", "-e", str(dossier / "etape.sh")], cwd=cwd or self.depot, env=tout, capture_output=True, text=True)
        lire = lambda nom: (dossier / nom).read_text(encoding="utf-8") if (dossier / nom).exists() else ""  # noqa: E731
        return r, dict(l.split("=", 1) for l in lire("sortie").splitlines()), lire("gh.log")

    def test_workflow_step_asks_the_base_tool_and_main_and_fails_closed(self):
        """Replays validation.yml's scope step on a merge commit like GitHub's (first parent: the base)."""
        script = self.etapes()[1]["portee"]["run"]

        def etape(pr, outil_base=None, main="success"):
            git(self.depot, "checkout", "-q", "main")
            if outil_base == "absent":
                git(self.depot, "rm", "-q", "outils/bee.py")
            elif outil_base:
                self.ecrire("outils/bee.py", outil_base)
            base = self.commit()
            git(self.depot, "checkout", "-q", "-b", f"pr-{len(etapes)}")
            pr()
            self.commit()
            git(self.depot, "checkout", "-q", "--detach", base)
            git(self.depot, "-c", "user.name=t", "-c", "user.email=t@t", "merge", "-q", "--no-ff", "--no-edit", f"pr-{len(etapes)}")
            r, sorties, appels = self.rejouer(script, {"BASE_EVENEMENT": "0" * 40, "FAUX_GH": main})
            self.assertEqual(r.returncode, 0, r.stdout + r.stderr)
            self.assertEqual(sorties["base"], base)
            self.assertIn(sorties["portee"], ("data", "full"))
            etapes.append(sorties["portee"])
            return appels

        etapes = []
        appels = etape(lambda: self.ecrire("membres/alice.yaml"))
        requete = appels.split()[1]
        self.assertTrue(requete.startswith("repos/Bee-ruche/registre/actions/workflows/validation.yml/runs?"), appels)
        self.assertLessEqual({"branch=main", "event=push", "status=completed"}, set(requete.split("?", 1)[1].split("&")))
        etape(lambda: self.ecrire("outils/bee.py", "print('data')\n"))  # the PR's own tool never decides
        etape(lambda: self.ecrire("membres/bruno.yaml"), main="failure")  # a red main: every PR runs the full suite
        etape(lambda: self.ecrire("membres/bruno.yaml"), main="error")  # main's last run unreadable
        etape(lambda: self.ecrire("membres/bruno.yaml"), main="")
        etape(lambda: self.ecrire("membres/bruno.yaml"), outil_base="print('data')\nraise SystemExit(2)\n")
        etape(lambda: self.ecrire("membres/chloe.yaml"), outil_base="print('data ')\n")
        etape(lambda: self.ecrire("membres/chloe.yaml"), outil_base="absent")
        self.assertEqual(etapes, ["data"] + ["full"] * 7)
        # No merge commit and no event base: the step fails before any tool runs (git show ":path" would read the index).
        git(self.depot, "checkout", "-q", "main")
        r, sorties, appels = self.rejouer(script, {"BASE_EVENEMENT": "", "FAUX_GH": "success"})
        self.assertNotEqual(r.returncode, 0)
        self.assertEqual((sorties, appels), ({}, ""))

    @staticmethod
    def tourne(etape, evenement, portee):
        """Whether a step runs: evaluates only the `if:` shapes validation.yml uses (GitHub compares strings ignoring case);
        any other shape fails the test, to be added here knowingly."""
        condition = etape.get("if")
        if condition is None:
            return True
        forme = re.fullmatch(r"(github\.event_name|steps\.portee\.outputs\.portee) (==|!=) '([a-z_]+)'", str(condition).strip())
        if not isinstance(condition, str) or not forme:
            raise AssertionError(f"{etape.get('name')}: unknown if: {condition!r}")
        valeur = evenement if forme[1] == "github.event_name" else (portee or "")
        return (valeur.lower() == forme[3]) == (forme[2] == "==")

    def test_wiring_of_each_step(self):
        """S1 (review): which steps run, for each event and each output of the scope step; the PR rules take the scope
        step's base, and stop on an empty one."""
        etapes, roles = self.etapes()
        for evenement in ("push", "pull_request"):
            for sortie in (None, "", "full", "data", "garbage", "DATA"):
                portee = sortie if self.tourne(roles["portee"], evenement, None) else None
                donnees = evenement == "pull_request" and str(portee).lower() == "data"
                attendu = {id(roles["portee"]): evenement == "pull_request", id(roles["regles"]): evenement == "pull_request",
                           id(roles["outil"]): not donnees, id(roles["juge"]): not donnees, id(roles["reel"]): donnees}
                for etape in etapes:  # every other step, « Validation complète » included, always runs
                    with self.subTest(evenement=evenement, portee=sortie, etape=etape.get("name") or etape.get("uses")):
                        self.assertEqual(self.tourne(etape, evenement, portee), attendu.get(id(etape), True))
        flux = yaml.safe_load((RACINE / ".github/workflows/validation.yml").read_text(encoding="utf-8"))
        self.assertEqual(flux["permissions"], {"contents": "read", "actions": "read"})
        self.assertEqual(roles["portee"]["env"]["GH_TOKEN"], "${{ github.token }}")
        self.assertIn("main=$(timeout 60 gh api ", roles["portee"]["run"])  # the stub gh ignores --jq: the expression is read here
        self.assertIn("--jq '.workflow_runs[0].conclusion') || main=unknown", roles["portee"]["run"])
        self.assertEqual(roles["regles"]["env"]["BASE"], "${{ steps.portee.outputs.base }}")
        self.assertNotRegex(roles["regles"]["run"], r"(?m)^\s*BASE=")
        r, _, appels = self.rejouer(roles["regles"]["run"], {"BASE": "", "AUTEUR": "alice", "FAUX_GH": "2020-01-01"})
        self.assertNotEqual(r.returncode, 0, "an empty base compares HEAD with itself and passes")
        self.assertEqual(appels, "")

    def test_both_workflows_give_the_gate_github_s_record_of_the_push(self):
        """ruche-0091: the PR rules take the time of the PR from this run's creation (the API, read with the run's id), and
        stop if it is unreadable; fusion-auto takes the creation of the validation run that the push triggered."""
        regles = self.etapes()[1]["regles"]["run"]
        self.assertIn('instant=$(timeout 60 gh api "repos/$GITHUB_REPOSITORY/actions/runs/$GITHUB_RUN_ID" --jq .created_at)', regles)
        faux_bee = pathlib.Path(tempfile.mkdtemp(dir=self.temp.name))
        (faux_bee / "outils").mkdir()
        (faux_bee / "outils/bee.py").write_text("import sys\nprint('BEE', *sys.argv[1:])\n", encoding="utf-8")
        env = {"BASE": "abc", "AUTEUR": "alice", "GITHUB_RUN_ID": "4242"}
        r, _, appels = self.rejouer(regles, {**env, "FAUX_GH": "2026-10-27T12:00:00Z"}, cwd=faux_bee)
        self.assertEqual(r.returncode, 0, r.stdout + r.stderr)
        self.assertIn("api repos/Bee-ruche/registre/actions/runs/4242 --jq .created_at", appels)
        self.assertTrue(r.stdout.rstrip().endswith("--instant-pr 2026-10-27T12:00:00Z"), r.stdout)
        (faux_bee / "bin").mkdir()  # a gh that answers for the account, not for the run
        (faux_bee / "bin/gh").write_text('#!/bin/sh\ncase "$*" in *actions/runs/*) exit 1;; esac\necho 2020-01-01\n', encoding="utf-8")
        (faux_bee / "bin/gh").chmod(0o755)
        r = subprocess.run(["bash", "-e", "-c", regles], cwd=faux_bee, capture_output=True, text=True,
                           env={**os.environ, **env, "PATH": f"{faux_bee / 'bin'}{os.pathsep}{os.environ['PATH']}",
                                "GITHUB_REPOSITORY": "Bee-ruche/registre"})
        self.assertNotEqual(r.returncode, 0)
        self.assertNotIn("BEE", r.stdout, "the gate never runs without GitHub's record")
        etape = next(s for s in yaml.safe_load((RACINE / ".github/workflows/fusion-auto.yml").read_text(encoding="utf-8"))["jobs"]
                     ["fusionner"]["steps"] if s.get("name", "").startswith("Vérifier la fusion simulée"))
        self.assertEqual(etape["env"]["INSTANT_PR"], "${{ github.event.workflow_run.created_at }}")
        self.assertRegex(etape["run"], r'verifier-pr [^\n]*\\\n[^\n]*--instant-pr "\$INSTANT_PR"\n')

    def test_the_data_only_step_runs_exactly_the_tests_allowed_to_read_live_data(self):
        """One list: on a data-only PR, validation.yml runs TESTS_REGISTRE_REEL, the tests the audit hook lets read the live
        registry's data; each exists."""
        commande = self.etapes()[1]["reel"]["run"].split()
        self.assertEqual(commande[:3], ["python3", "-m", "unittest"])
        self.assertEqual(sorted(commande[3:]), sorted(f"outils.test_bee.{n}" for n in TESTS_REGISTRE_REEL))
        for nom in TESTS_REGISTRE_REEL:
            classe, _, methode = nom.partition(".")
            self.assertTrue(issubclass(globals()[classe], unittest.TestCase), nom)
            self.assertTrue(not methode or callable(getattr(globals()[classe], methode, None)), nom)

    def test_the_audit_hook_fails_a_test_that_reads_live_data(self):
        """S2 (review): however the path is built, in this process or in a subprocess, a test outside TESTS_REGISTRE_REEL
        that reads a live data folder fails; the controls (reading elsewhere, rmtree and git -C elsewhere from the repository
        root) do not."""
        racine, copie, ailleurs = RACINE, pathlib.Path(self.temp.name) / "copie", pathlib.Path(self.temp.name) / "ailleurs"
        tache = "taches/ruche/ruche-0090.yaml"

        class Lecteur(unittest.TestCase):
            def depuis_la_racine(self):
                self.addCleanup(os.chdir, os.getcwd())
                os.chdir(RACINE)

            def test_bee_without_registre(self):
                lancer("lister", "--json")

            def test_registre_of_the_repository(self):
                bee.Registre(pathlib.Path(bee.__file__).resolve().parent.parent)

            def test_joinpath(self):
                list(RACINE.joinpath("taches").glob("*/*.yaml"))

            def test_alias(self):
                next((racine / "taches").iterdir())

            def test_rglob(self):
                list(RACINE.rglob("D-0001.yaml"))

            def test_copy(self):
                shutil.copytree(RACINE / "debats", copie)

            def test_relative_open(self):
                self.depuis_la_racine()
                with contextlib.suppress(OSError):
                    open(tache, encoding="utf-8").close()

            def test_relative_os_open(self):
                self.depuis_la_racine()
                with contextlib.suppress(OSError):
                    os.close(os.open(tache, os.O_RDONLY))

            def test_registre_dot(self):
                self.depuis_la_racine()
                bee.Registre(".")

            def test_cat(self):
                subprocess.run(["cat", RACINE / tache], capture_output=True)

            def test_git_ls_files(self):
                git(RACINE, "ls-files", "taches")

            def test_bee_in_a_data_folder(self):
                subprocess.run([sys.executable, str(RACINE / "outils/bee.py"), "--version"], cwd=RACINE / "taches", capture_output=True)

            def test_control_outside_the_data_folders(self):
                (RACINE / "bee.yaml").read_text(encoding="utf-8")
                list((RACINE / "outils").glob("*.py"))
                git(RACINE, "rev-parse", "HEAD")
                subprocess.run(["cat", RACINE / "bee.yaml"], capture_output=True)

            def test_control_rmtree_and_git_elsewhere_from_the_repository_root(self):
                (ailleurs / "taches/ruche").mkdir(parents=True)
                (ailleurs / tache).write_text("id: x\n", encoding="utf-8")
                self.depuis_la_racine()
                subprocess.run(["git", "-C", str(ailleurs), "ls-files", "taches"], capture_output=True)
                subprocess.run(["ls", "taches"], cwd=ailleurs, capture_output=True)
                shutil.rmtree(ailleurs)  # os.open of bare names relative to directory descriptors

        resultat = unittest.TestResult()
        unittest.defaultTestLoader.loadTestsFromTestCase(Lecteur).run(resultat)
        self.assertEqual(resultat.errors, [])
        echecs = {t._testMethodName: texte for t, texte in resultat.failures}
        self.assertEqual(sorted(echecs), sorted(n for n in dir(Lecteur) if n.startswith("test_") and not n.startswith("test_control_")))
        for texte in echecs.values():
            self.assertIn("reads the live registry's data", texte)


class BaseTest(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.dossier = pathlib.Path(self.temp.name) / "registre"
        # Le dépôt sans les données du registre réel, puis le jeu figé (JEU_FIGE) : les tests ne dépendent ni des réservations
        # en cours (R8 : 3 au plus), ni des propositions de règle, des votes et des débats réels (leurs numéros, rapporteurs et
        # dates : les tests numérotent et datent les leurs), ni du nombre de tâches.
        shutil.copytree(RACINE, self.dossier, ignore=sans_donnees_reelles)
        shutil.copytree(JEU_FIGE, self.dossier, dirs_exist_ok=True)
        # L'arbre est le vrai : un nœud confié depuis le gel à une tâche absente du jeu figé (entretenu_par) l'y trouve, en
        # tâche fictive, pour que le registre des tests reste valide.
        for sens in sorted((self.dossier / "arbre").rglob(bee.FICHIER_NOEUD)):
            tid = bee.lire_noeud(sens.read_text(encoding="utf-8"), str(sens))[0]["entete"].get("entretenu_par")
            projet = tid.rsplit("-", 1)[0] if isinstance(tid, str) and re.fullmatch(r"[a-z0-9-]+-\d{4}", tid) else None
            fiche_projet = self.dossier / "projets" / f"{projet}.yaml"
            chemin = self.dossier / "taches" / str(projet) / f"{tid}.yaml"
            if projet and fiche_projet.exists() and not chemin.exists():
                chemin.parent.mkdir(exist_ok=True)
                categorie = bee.lire_yaml(fiche_projet)["categorie"]
                chemin.write_text(TACHE_OPTIMISATION.replace("miniz-0099", tid).replace("projet: miniz", f"projet: {projet}")
                                  .replace("categorie: compression-sans-perte", f"categorie: {categorie}")
                                  .replace("type: optimisation", "type: test").replace("metrique: debit_compression_n6", "metrique: null")
                                  .replace("sortie_compressee: identique\n", ""), encoding="utf-8")
        questions = self.dossier / "docs" / "questions-ouvertes.md"
        questions.write_text(re.sub(r"(?m)^ *(?:Débat :|Debate:) \[D-\d{4}\]\(\.\./debats/D-\d{4}\.yaml\) \(`bee debats --voir D-\d{4}`\)\.\n", "",
                                    questions.read_text(encoding="utf-8")), encoding="utf-8")
        # Ni de la valeur courante de la porte de relecture (R3) : les tests partent de la porte fermée (« true ») et
        # la règlent eux-mêmes (regler_porte, regler_porte_humaine).
        chemin_config = self.dossier / "bee.yaml"
        chemin_config.write_text(re.sub(r"(?m)^relecture_gardien_requise: *[a-z_]+", "relecture_gardien_requise: true",
                                        chemin_config.read_text(encoding="utf-8")), encoding="utf-8")
        (self.dossier / "taches" / "miniz" / "miniz-0099.yaml").write_text(TACHE_OPTIMISATION, encoding="utf-8")
        # Tâches fictives indépendantes de l'état réel du registre : 9002 attend 9001.
        (self.dossier / "taches" / "miniz" / "miniz-9001.yaml").write_text(TACHE_OPTIMISATION.replace("miniz-0099", "miniz-9001"), encoding="utf-8")
        (self.dossier / "taches" / "miniz" / "miniz-9002.yaml").write_text(
            TACHE_OPTIMISATION.replace("miniz-0099", "miniz-9002").replace("type: optimisation", "type: test").replace("metrique: debit_compression_n6", "metrique: null")
            .replace("sortie_compressee: identique\n", "").replace("statut: ouverte", "depend_de: [miniz-9001]\nstatut: ouverte"), encoding="utf-8")
        self.ancien_maintenant = os.environ.get("BEE_MAINTENANT")
        os.environ["BEE_MAINTENANT"] = "2026-10-27T12:00:00Z"
        for pseudo in ("alice", "bruno", "chloe"):
            code, texte = self.bee("inscrire", "--pseudo", pseudo, "--compte-cree-le", "2020-01-01")
            self.assertEqual(code, 0, texte)

    def tearDown(self):
        if self.ancien_maintenant is None:
            os.environ.pop("BEE_MAINTENANT", None)
        else:
            os.environ["BEE_MAINTENANT"] = self.ancien_maintenant
        self.temp.cleanup()

    def bee(self, *arguments):
        return lancer("--registre", str(self.dossier), *arguments)

    def valide(self):
        code, texte = self.bee("valider")
        self.assertEqual(code, 0, texte)

    def lu(self, cid):
        """--commit d'un relecteur qui a lu le commit du verdict courant (bee relire, ruche-0028) ; rien avant le verdict."""
        enr = bee.lire_yaml(self.dossier / "contributions" / cid.split("-")[0] / f"{cid}.yaml")
        sha = (enr.get("verdict") or {}).get("sha") if isinstance(enr, dict) else None
        return ["--commit", sha] if sha else []

    def tache(self, identifiant):
        projet = identifiant.rsplit("-", 1)[0]
        return bee.lire_yaml(self.dossier / "taches" / projet / f"{identifiant}.yaml")

    def fichiers_pr(self, *chemins):
        """Liste des fichiers d'une PR, telle que le workflow du registre la lit auprès de l'API GitHub."""
        chemin = self.dossier / "fichiers-pr.txt"
        chemin.write_text("\n".join(chemins or ("miniz_tdef.c",)) + "\n", encoding="utf-8")
        return str(chemin)

    def soumettre_0099(self, auteur="alice"):
        self.assertEqual(self.bee("prendre", "miniz-0099", "--utilisateur", auteur)[0], 0)
        code, texte = self.bee("soumettre", "miniz-0099", "--utilisateur", auteur,
                               "--pr", "https://github.com/Bee-ruche/minizBee/pull/99007", "--resume", "Essai.")
        self.assertEqual(code, 0, texte)
        return "miniz-0099-c1"

    def contributeurs(self, *pseudos):
        """Fait de chacun un Contributeur : une contribution intégrée à son nom, sur une tâche fictive (miniz-91NN). La relecture
        d'un Nouveau ne compte pas pour R3 (docs/reputation.md, ruche-0011) : un test qui veut des relectures qui comptent les
        fait faire par des Contributeurs, dont le vote pèse alors 1 (le seuil de vote suit)."""
        for pseudo in pseudos:
            numero = 9100 + len(list((self.dossier / "taches/miniz").glob("miniz-91*.yaml")))
            tid = f"miniz-{numero}"
            (self.dossier / f"taches/miniz/{tid}.yaml").write_text(
                TACHE_OPTIMISATION.replace("miniz-0099", tid).replace("statut: ouverte", f"statut: integree\ncontribution: {tid}-c1"),
                encoding="utf-8")
            bee.ecrire_yaml(self.dossier / f"contributions/miniz/{tid}-c1.yaml", {
                "id": f"{tid}-c1", "tache": tid, "auteur": pseudo, "pr": f"https://github.com/Bee-ruche/minizBee/pull/{numero}",
                "statut": "integree", "soumise_le": "2026-10-20T12:00:00Z", "relectures": []})
        niveaux = bee.calculer_niveaux(bee.Registre(self.dossier))
        self.assertEqual({bee.niveau_de(niveaux, p) for p in pseudos}, {"Contributeur"})


class TestRegistre(BaseTest):
    def test_le_registre_livre_est_valide(self):
        code, texte = lancer("--registre", str(RACINE), "valider")
        self.assertEqual(code, 0, texte)

    def test_inscription_compte_trop_recent(self):
        code, texte = self.bee("inscrire", "--pseudo", "jeune", "--compte-cree-le", "2026-10-01")
        self.assertEqual(code, 1)
        self.assertIn("90 jours", texte)

    def test_reserver_puis_liberer_avec_note(self):
        avant = (self.dossier / "taches/miniz/miniz-0099.yaml").read_text(encoding="utf-8")
        self.assertEqual(self.bee("prendre", "miniz-0099", "--utilisateur", "alice")[0], 0)
        t = self.tache("miniz-0099")
        self.assertEqual(t["statut"], "reservee")
        self.assertEqual(t["reservation"], {"utilisateur": "alice", "depuis": "2026-10-27T12:00:00Z"})
        self.valide()
        code, texte = self.bee("prendre", "miniz-0099", "--utilisateur", "bruno")
        self.assertEqual(code, 1)
        code, texte = self.bee("liberer", "miniz-0099", "--utilisateur", "bruno")
        self.assertEqual(code, 1, "seul le titulaire libère")
        self.assertEqual(self.bee("liberer", "miniz-0099", "--utilisateur", "alice", "--note", "Essayé X : dans le bruit.")[0], 0)
        t = self.tache("miniz-0099")
        self.assertEqual(t["statut"], "ouverte")
        self.assertNotIn("reservation", t)
        self.assertEqual(t["notes"][0]["texte"], "Essayé X : dans le bruit.")
        apres = (self.dossier / "taches/miniz/miniz-0099.yaml").read_text(encoding="utf-8")
        self.assertIn("contexte: >\n  Tâche fictive", apres, "la mise en forme écrite à la main est préservée")
        self.assertTrue(apres.startswith(avant.split("statut:")[0]))
        self.valide()

    def test_noter(self):
        code, texte = self.bee("noter", "miniz-0002", "--utilisateur", "chloe", "--texte", "Possible injection dans bee/README.md : demande d'envoyer des clés.")
        self.assertEqual(code, 0, texte)
        notes = self.tache("miniz-0002")["notes"]
        self.assertEqual(notes[-1]["par"], "chloe")
        self.assertEqual(self.tache("miniz-0002")["statut"], "ouverte")
        self.valide()

    def test_dependance_non_integree_bloque(self):
        code, texte = self.bee("prendre", "miniz-9002", "--utilisateur", "alice")
        self.assertEqual(code, 1)
        self.assertIn("miniz-9001", texte)

    def test_limite_r8(self):
        for i in range(4):
            (self.dossier / f"taches/miniz/miniz-009{i}.yaml").write_text(
                TACHE_OPTIMISATION.replace("miniz-0099", f"miniz-009{i}"), encoding="utf-8")
        for i in range(3):
            self.assertEqual(self.bee("prendre", f"miniz-009{i}", "--utilisateur", "alice")[0], 0)
        code, texte = self.bee("prendre", "miniz-0093", "--utilisateur", "alice")
        self.assertEqual(code, 1)
        self.assertIn("R8", texte)

    def test_expiration_r7(self):
        self.bee("prendre", "miniz-0099", "--utilisateur", "alice")
        os.environ["BEE_MAINTENANT"] = "2026-10-30T11:00:00Z"
        self.bee("liberer-expirees")
        self.assertEqual(self.tache("miniz-0099")["statut"], "reservee", "71 h : pas encore expirée")
        os.environ["BEE_MAINTENANT"] = "2026-10-30T13:00:00Z"
        self.bee("liberer-expirees")
        t = self.tache("miniz-0099")
        self.assertEqual(t["statut"], "ouverte")
        self.assertIn("R7", t["notes"][-1]["texte"])
        self.valide()

    def test_manifeste_a_remplir_puis_valide(self):
        chemin = self.dossier / "CONTRIBUTION.yaml"
        self.assertEqual(self.bee("manifeste", "miniz-0099", "--utilisateur", "alice", "--sortie", str(chemin))[0], 0)
        code, texte = self.bee("valider-contribution", str(chemin))
        self.assertEqual(code, 1)
        self.assertIn("À REMPLIR", texte)
        chemin.write_text(MANIFESTE_REMPLI, encoding="utf-8")
        code, texte = self.bee("valider-contribution", str(chemin))
        self.assertEqual(code, 0, texte)

    def test_manifeste_sans_mesure_refuse(self):
        chemin = self.dossier / "CONTRIBUTION.yaml"
        chemin.write_text(MANIFESTE_REMPLI.split("mesures:")[0] + "teste: [tests]\nnon_teste: []\ndoutes: Aucun.\ntaille_reelle: S\n", encoding="utf-8")
        code, texte = self.bee("valider-contribution", str(chemin))
        self.assertEqual(code, 1)
        self.assertIn("commandement 2", texte)

    def test_soumission_relecture_vote_verdict_score(self):
        self.contributeurs("bruno")  # sa relecture compte pour la confiance C (pas celle d'un Nouveau)
        cid = self.soumettre_0099()
        t = self.tache("miniz-0099")
        self.assertEqual(t["statut"], "en_relecture")
        self.assertEqual(t["contribution"], cid)
        self.valide()
        self.assertEqual(self.bee("relire", cid, *self.lu(cid), "--utilisateur", "alice", "--avis", "favorable", "--motif", "Ma propre contribution.")[0], 1)
        self.assertEqual(self.bee("relire", cid, *self.lu(cid), "--utilisateur", "bruno", "--avis", "favorable", "--motif", "Diff relu en entier.")[0], 0)
        self.assertEqual(self.bee("relire", cid, *self.lu(cid), "--utilisateur", "bruno", "--avis", "favorable", "--motif", "Encore une fois.")[0], 1)
        self.assertEqual(self.bee("voter", cid, "--utilisateur", "alice", "--valeur", "1")[0], 1)
        code, texte = self.bee("voter", cid, "--utilisateur", "chloe", "--valeur", "1")
        self.assertEqual(code, 0, texte)
        self.assertIn("Niveau Nouveau : votre vote est public, mais il pèse 0", texte, "tour 2 : la Nouvelle le sait")
        self.valide()
        verdict = self.dossier / "verdict.json"
        verdict.write_text(json.dumps({"ci": "verte", "gain": 0.03, "au_dela_du_bruit": True, "lignes_modifiees": 10, "amorcage": True}), encoding="utf-8")
        manifeste = self.dossier / "CONTRIBUTION.yaml"
        manifeste.write_text(MANIFESTE_REMPLI, encoding="utf-8")
        code, texte = self.bee("enregistrer-verdict", cid, "--verdict", str(verdict), "--manifeste", str(manifeste), "--sha", "abc1234")
        self.assertEqual(code, 0, texte)
        self.assertIn("écart", texte, "gain déclaré 10 % contre 3 % mesuré : alerte")
        # ruche-0012 : la relecture d'avant le verdict ne compte ni pour R3 ni pour la confiance C ; bruno relit le commit jugé.
        self.assertEqual(self.bee("relire", cid, *self.lu(cid), "--utilisateur", "bruno", "--avis", "favorable", "--motif", "Commit jugé relu.")[0], 0)
        enr = bee.lire_yaml(self.dossier / f"contributions/miniz/{cid}.yaml")
        self.assertEqual(enr["verdict"]["ecart_declare"], 0.07)
        self.assertTrue(enr["verdict"]["amorcage"])
        self.valide()
        # L'alerte se lit aussi là où le relecteur regarde, pas seulement dans le journal de la CI (tour 2).
        for commande in (["verifier-acceptation", cid], ["classement"]):
            self.assertIn(f"⚠ {cid} : écart de 7.0 points", self.bee(*commande)[1], commande[0])
        # Le manifeste d'une autre tâche (CONTRIBUTION.yaml resté sur master) n'est jamais comparé : pas d'écart inventé.
        manifeste.write_text(MANIFESTE_REMPLI.replace("tache: miniz-0099", "tache: miniz-0098"), encoding="utf-8")
        self.assertIn("tache: miniz-0098", manifeste.read_text(encoding="utf-8"))
        code, texte = self.bee("enregistrer-verdict", cid, "--verdict", str(verdict), "--manifeste", str(manifeste), "--sha", "abc1235")
        self.assertEqual(code, 0, texte)
        self.assertIn("manifeste ignoré (tâche miniz-0098, pas miniz-0099)", texte)
        self.assertNotIn("ecart_declare", bee.lire_yaml(self.dossier / f"contributions/miniz/{cid}.yaml")["verdict"])
        for illisible in ("- une liste\n", "\x00\x9e\xe9"):
            manifeste.write_text(illisible, encoding="utf-8")
            code, texte = self.bee("enregistrer-verdict", cid, "--verdict", str(verdict), "--manifeste", str(manifeste), "--sha", "abc1236")
            self.assertEqual(code, 0, texte)
            self.assertIn("manifeste ignoré (tâche illisible", texte)
        code, texte = self.bee("enregistrer-verdict", cid, "--verdict", str(verdict), "--manifeste", str(self.dossier / "MANIFESTE_ABSENT.yaml"), "--sha", "abc1237")
        self.assertEqual(code, 0, texte)
        manifeste.write_text(MANIFESTE_REMPLI, encoding="utf-8")
        self.bee("enregistrer-verdict", cid, "--verdict", str(verdict), "--manifeste", str(manifeste), "--sha", "abc1234")
        enr = bee.lire_yaml(self.dossier / f"contributions/miniz/{cid}.yaml")
        reg = bee.Registre(self.dossier)
        score = bee.calculer_score(reg, enr, bee.calculer_niveaux(reg))
        # G 0,03 × P 1 × C 1/3 / (1 + 10/100) × V 1 (chloé est Nouvelle : poids 0)
        self.assertAlmostEqual(score["S"], 0.03 / 3 / 1.1)
        self.assertEqual(score["V"], 1.0)

    def test_un_manifeste_mal_forme_ne_fait_ni_perdre_le_verdict_ni_un_ecart_non_fini(self):
        """Revue adverse du tour 2 : mesures en liste, valeur en texte, nombre démesuré ou NaN faisaient planter
        enregistrer-verdict (verdict perdu) ou inscrivaient un écart NaN qu'aucune alerte ne voyait."""
        cid = self.soumettre_0099()
        verdict = self.dossier / "verdict.json"
        verdict.write_text(json.dumps({"ci": "verte", "gain": 0.03, "au_dela_du_bruit": True, "lignes_modifiees": 10}), encoding="utf-8")
        base = yaml.safe_load(MANIFESTE_REMPLI)
        cas = {"mesures en liste": {**base, "mesures": [1, 2]},
               "avant en texte": {**base, "mesures": {"avant": {"debit_compression_n6": "abc"}, "apres": {"debit_compression_n6": 55.0}}},
               "après démesuré": {**base, "mesures": {"avant": {"debit_compression_n6": 1}, "apres": {"debit_compression_n6": 10 ** 400}}},
               "après NaN": {**base, "mesures": {"avant": {"debit_compression_n6": 50.0}, "apres": {"debit_compression_n6": float("nan")}}},
               "avant nul": {**base, "mesures": {"avant": {"debit_compression_n6": 0}, "apres": {"debit_compression_n6": 55.0}}}}
        manifeste = self.dossier / "manifeste.yaml"
        for nom, contenu in cas.items():
            with self.subTest(cas=nom):
                manifeste.write_text(yaml.safe_dump(contenu, allow_unicode=True), encoding="utf-8")
                code, texte = self.bee("enregistrer-verdict", cid, "--verdict", str(verdict), "--manifeste", str(manifeste),
                                       "--sha", "abc1234")
                self.assertEqual(code, 0, texte)
                enr = bee.lire_yaml(self.dossier / f"contributions/miniz/{cid}.yaml")
                self.assertEqual(enr["verdict"]["ci"], "verte")
                self.assertIsNone(enr["verdict"].get("ecart_declare"))
        self.valide()

