    def test_inscription_et_date_github(self):
        git(self.dossier, "switch", "-qc", "i")
        self.bee("inscrire", "--pseudo", "david", "--compte-cree-le", "2021-05-05")
        self.commit()
        self.assertEqual(self.verifier("david", "--compte-cree-le", "2021-05-05")[0], 0)
        self.assertEqual(self.verifier("david", "--compte-cree-le", "2026-10-20")[0], 1, "date déclarée ≠ date GitHub")
        self.assertEqual(self.verifier("eve")[0], 1, "on ne s'inscrit qu'en son nom")

    # --- ruche-0039: the dates of a member file are checked at the time of the PR (BEE_MAINTENANT: 2026-10-27T12:00Z) ---

    def member_pr(self, branch, pseudo="david", **dates):
        """A PR adding membres/<pseudo>.yaml in bee inscrire's form, with the given dates (by default, honest ones)."""
        git(self.dossier, "switch", "-qf", "main")
        git(self.dossier, "switch", "-qc", branch)
        bee.ecrire_yaml(self.dossier / f"membres/{pseudo}.yaml",
                        {"pseudo": pseudo, "inscrit_le": "2026-10-27", "compte_cree_le": "2021-05-05", "github_id": numero_de(pseudo), **dates})
        self.commit()

    def test_each_member_date_outside_its_tolerance_is_refused(self):
        """inscrit_le is the PR's day; compte_cree_le is GitHub's date. Earlier or later than that, each one is refused."""
        self.member_pr("honest")
        code, texte = self.verifier("david", "--compte-cree-le", "2021-05-05", "--fusion-auto")
        self.assertEqual(code, 0, texte)
        self.assertIn("FUSION_AUTO=oui", texte)
        for champ, valeur, morceau in (
                ("inscrit_le", "2026-10-26", "inscrit_le (2026-10-26) must be the date of the PR (2026-10-27)"),
                ("inscrit_le", "2020-01-01", "inscrit_le (2020-01-01) must be the date of the PR"),
                ("inscrit_le", "2026-10-28", "inscrit_le (2026-10-28) must be the date of the PR"),
                ("inscrit_le", "2099-01-01", "inscrit_le (2099-01-01) must be the date of the PR"),
                ("compte_cree_le", "2021-05-04", "compte_cree_le ne correspond pas à la date fournie par GitHub (2021-05-05)"),
                ("compte_cree_le", "2015-01-01", "compte_cree_le ne correspond pas à la date fournie par GitHub (2021-05-05)"),
                ("compte_cree_le", "2021-05-06", "compte_cree_le ne correspond pas à la date fournie par GitHub (2021-05-05)"),
                ("compte_cree_le", "2026-10-27", "compte_cree_le ne correspond pas à la date fournie par GitHub (2021-05-05)")):
            with self.subTest(champ=champ, valeur=valeur):
                self.member_pr(f"{champ}-{valeur}", **{champ: valeur})
                code, texte = self.verifier("david", "--compte-cree-le", "2021-05-05")
                self.assertEqual(code, 1, texte)
                self.assertIn(morceau, texte)

    def test_a_file_written_by_bee_inscrire_is_accepted(self):
        """Written at 23:30 UTC, the file passes on its day and within 2 h after midnight (TOLERANCE_DATE), as cree_le does."""
        os.environ["BEE_MAINTENANT"] = "2026-10-27T23:30:00Z"
        git(self.dossier, "switch", "-qc", "inscription")
        code, texte = self.bee("inscrire", "--pseudo", "david", "--compte-cree-le", "2021-05-05")
        self.assertEqual(code, 0, texte)
        self.commit()
        for instant in ("2026-10-27T23:30:00Z", "2026-10-28T01:30:00Z"):
            with self.subTest(instant=instant):
                os.environ["BEE_MAINTENANT"] = instant
                code, texte = self.verifier("david", "--compte-cree-le", "2021-05-05", "--fusion-auto")
                self.assertEqual(code, 0, texte)
                self.assertIn("FUSION_AUTO=oui", texte)
                self.assertIn("inscription", texte)
        os.environ["BEE_MAINTENANT"] = "2026-10-28T02:30:00Z"
        code, texte = self.verifier("david", "--compte-cree-le", "2021-05-05")
        self.assertEqual(code, 1, texte)
        self.assertIn("inscrit_le (2026-10-27) must be the date of the PR (2026-10-28)", texte)

    def test_account_age_is_measured_at_the_check_from_github(self):
        """The age depends only on GitHub's creation date and the instant of the check; without GitHub's date, a registration
        is refused."""
        age_89, age_90 = "2026-07-30", "2026-07-29"  # on 2026-10-27
        self.member_pr("age-90", compte_cree_le=age_90)
        code, texte = self.verifier("david", "--compte-cree-le", age_90)
        self.assertEqual(code, 0, texte)
        self.member_pr("age-89", compte_cree_le=age_89)
        code, texte = self.verifier("david", "--compte-cree-le", age_89)
        self.assertEqual(code, 1, texte)
        self.assertIn("le compte GitHub doit avoir au moins 90 jours", texte)
        # The next day, within 2 h of midnight: 90 days at the check, so the same file passes.
        os.environ["BEE_MAINTENANT"] = "2026-10-28T01:00:00Z"
        code, texte = self.verifier("david", "--compte-cree-le", age_89)
        self.assertEqual(code, 0, texte)
        os.environ["BEE_MAINTENANT"] = "2026-10-27T12:00:00Z"
        for inscrit_le in ("2026-12-01", "2027-10-27"):
            with self.subTest(inscrit_le=inscrit_le):
                self.member_pr(f"age-{inscrit_le}", compte_cree_le=age_89, inscrit_le=inscrit_le)
                code, texte = self.verifier("david", "--compte-cree-le", age_89)
                self.assertEqual(code, 1, texte)
                self.assertIn("le compte GitHub doit avoir au moins 90 jours", texte)
        self.member_pr("sans-github")
        for options in ((), ("--compte-cree-le", ""), ("--compte-cree-le", "inconnue")):
            with self.subTest(options=options):
                code, texte = self.verifier("david", *options)
                self.assertEqual(code, 1, texte)
                self.assertNotIn("Traceback", texte)
        self.assertIn("registering requires the account creation date given by GitHub", self.verifier("david")[1])

    def test_member_dates_are_taken_in_utc(self):
        """The PR's day and the account's age are taken in UTC, whatever the offset of the instant of the check."""
        os.environ["BEE_MAINTENANT"] = "2026-10-28T01:30:00+02:00"  # 2026-10-27T23:30Z
        self.member_pr("utc")
        code, texte = self.verifier("david", "--compte-cree-le", "2021-05-05")
        self.assertEqual(code, 0, texte)
        self.member_pr("utc-next-day", inscrit_le="2026-10-28")
        code, texte = self.verifier("david", "--compte-cree-le", "2021-05-05")
        self.assertEqual(code, 1, texte)
        self.assertIn("inscrit_le (2026-10-28) must be the date of the PR (2026-10-27) : delete membres/david.yaml, then rerun "
                      "bee inscrire", texte)
        self.member_pr("utc-age", compte_cree_le="2026-07-30")  # 89 days on 2026-10-27
        code, texte = self.verifier("david", "--compte-cree-le", "2026-07-30")
        self.assertEqual(code, 1, texte)
        self.assertIn("le compte GitHub doit avoir au moins 90 jours", texte)
        os.environ["BEE_MAINTENANT"] = "2026-10-27T20:00:00-05:00"  # 2026-10-28T01:00Z
        self.member_pr("utc-west", inscrit_le="2026-10-28")
        code, texte = self.verifier("david", "--compte-cree-le", "2021-05-05")
        self.assertEqual(code, 0, texte)

    # --- ruche-0091: the time of the PR is the time GitHub recorded for the push (--instant-pr), not the time of the check ---

    def test_member_file_is_dated_at_the_push_and_the_account_age_runs_to_the_check(self):
        """inscrit_le is the day of the push, even when the check runs the next day, and a later day is refused whenever the
        check runs; the account's age still runs to the check (as before), and a local run still takes the current time."""
        age_89, push = "2026-07-30", ("--instant-pr", "2026-10-27T12:00:00Z")  # 89 days old on 2026-10-27, 90 on 2026-10-28
        self.member_pr("late-check", compte_cree_le=age_89)  # inscrit_le 2026-10-27, as bee inscrire writes it at the push
        os.environ["BEE_MAINTENANT"] = "2026-10-28T09:00:00Z"
        code, texte = self.verifier("david", "--compte-cree-le", age_89, *push, "--fusion-auto")
        self.assertEqual(code, 0, texte)
        self.assertIn("FUSION_AUTO=oui", texte)
        code, texte = self.verifier("david", "--compte-cree-le", age_89)
        self.assertEqual(code, 1, texte)
        self.assertIn("inscrit_le (2026-10-27) must be the date of the PR (2026-10-28)", texte)
        os.environ["BEE_MAINTENANT"] = "2026-10-27T13:00:00Z"
        code, texte = self.verifier("david", "--compte-cree-le", age_89, *push)
        self.assertEqual(code, 1, texte)
        self.assertIn("le compte GitHub doit avoir au moins 90 jours", texte)
        self.member_pr("dated-after-the-push", inscrit_le="2026-10-28")
        os.environ["BEE_MAINTENANT"] = "2026-10-28T09:00:00Z"
        code, texte = self.verifier("david", "--compte-cree-le", "2021-05-05", *push)
        self.assertEqual(code, 1, texte)
        self.assertIn("inscrit_le (2026-10-28) must be the date of the PR (2026-10-27)", texte)

    def test_a_missing_or_malformed_time_of_the_push_is_refused(self):
        """In CI the time of the push comes from GitHub: empty, unreadable, without a time zone, or after the check, the PR
        is refused (fails closed), never checked at the current time instead."""
        git(self.dossier, "switch", "-qc", "reservation")
        self.assertEqual(self.bee("prendre", "miniz-0099", "--utilisateur", "alice")[0], 0)
        self.commit()
        self.assertEqual(self.verifier("alice", "--instant-pr", "2026-10-27T12:01:00Z")[0], 0)
        for valeur in ("", "null", "garbage", "2026-10-27T12:00:00", "2026-10-27", "2026-10-27T12:01:01Z", "2099-01-01T00:00:00Z"):
            with self.subTest(valeur=valeur):
                code, texte = self.verifier("alice", "--instant-pr", valeur, "--fusion-auto")
                self.assertEqual(code, 1, texte)
                self.assertIn("--instant-pr", texte)
                self.assertNotIn("FUSION_AUTO", texte)
        # Review S1: a re-run keeps its run's creation time; older than 24 h at the check, it is refused.
        for maintenant, code in (("2026-10-28T11:00:00Z", 0), ("2026-10-28T12:00:00Z", 0), ("2026-10-28T12:00:01Z", 1),
                                 ("2026-10-28T13:00:00Z", 1)):
            with self.subTest(maintenant=maintenant):
                os.environ["BEE_MAINTENANT"] = maintenant
                code_lu, texte = self.verifier("alice", "--instant-pr", "2026-10-27T12:00:00Z")
                self.assertEqual(code_lu, code, texte)
                self.assertEqual("outside [the check - 24 h, the check + 1 min] : push again" in texte, bool(code))

    def test_an_existing_member_file_keeps_its_dates(self):
        """The dates of a registered member are not checked again against a later PR: a profile change passes, without
        GitHub's date; changing a date stays refused (only the preferred categories change)."""
        os.environ["BEE_MAINTENANT"] = "2026-12-15T12:00:00Z"
        chemin = self.dossier / "membres/alice.yaml"
        fiche = bee.lire_yaml(chemin)
        git(self.dossier, "switch", "-qc", "profil")
        bee.ecrire_yaml(chemin, {**fiche, "categories_preferees": ["compression-sans-perte"]})
        self.commit()
        code, texte = self.verifier("alice", "--fusion-auto")
        self.assertEqual(code, 0, texte)
        self.assertIn("FUSION_AUTO=oui", texte)
        self.assertIn("profil", texte)
        for champ in ("inscrit_le", "compte_cree_le"):
            with self.subTest(champ=champ):
                git(self.dossier, "switch", "-qf", "main")
                git(self.dossier, "switch", "-qc", f"profil-{champ}")
                bee.ecrire_yaml(chemin, {**fiche, champ: "2026-12-15"})
                self.commit()
                code, texte = self.verifier("alice", "--compte-cree-le", "2020-01-01")
                self.assertEqual(code, 1, texte)
                self.assertIn("seules les catégories préférées sont modifiables", texte)

    def test_relecture_et_note_falsifiees(self):
        cid = self.soumettre_0099()
        self.commit("soumission")
        git(self.dossier, "switch", "-qc", "relecture")
        chemin = self.dossier / f"contributions/miniz/{cid}.yaml"
        enr = bee.lire_yaml(chemin)
        enr["relectures"] = [{"relecteur": "chloe", "avis": "favorable", "motif": "Relecture au nom d'une autre.", "le": "2026-10-27T12:00:00Z"}]
        bee.ecrire_yaml(chemin, enr)
        self.commit()
        self.assertEqual(self.verifier("bruno")[0], 1)
        code, texte = self.verifier("chloe", "--fusion-auto")
        self.assertEqual(code, 0, texte)

    def test_motifs_courts_et_sans_caractere_cache(self):
        """Tour 2 (farid) : le motif d'une relecture n'avait aucun plafond, contrairement aux notes ; ni ceux d'un vote ou
        d'une mesure. Ils suivent maintenant notes.texte_max, et rien n'y est caché."""
        cid = self.soumettre_0099()
        self.commit("soumission")
        long = "Relu en entier. " + "x" * 1500
        self.assertIn("motif de 1516 caractères, au plus 1500", self.bee("relire", cid, *self.lu(cid), "--utilisateur", "chloe", "--avis",
                                                                           "favorable", "--motif", long)[1])
        self.assertIn("caractère invisible", self.bee("voter", cid, "--utilisateur", "chloe", "--valeur", "1", "--motif",
                                                      "Utile.‮")[1])
        for motif, attendu in ((long, "au plus 1500"), ("Relu en entier.​", "caractère invisible")):
            git(self.dossier, "switch", "-qC", "relecture", "main")
            chemin = self.dossier / f"contributions/miniz/{cid}.yaml"
            enr = bee.lire_yaml(chemin)
            enr["relectures"] = [{"relecteur": "chloe", "avis": "favorable", "motif": motif, "le": os.environ["BEE_MAINTENANT"]}]
            bee.ecrire_yaml(chemin, enr)
            self.commit()
            code, texte = self.verifier("chloe", "--fusion-auto")
            self.assertEqual(code, 1, texte)
            self.assertIn(attendu, texte)
            git(self.dossier, "switch", "-qC", "vote", "main")
            bee.ecrire_yaml(self.dossier / "votes" / cid / "chloe.yaml",
                            {"votant": "chloe", "sujet": cid, "valeur": 1, "motif": motif, "le": os.environ["BEE_MAINTENANT"]})
            self.commit()
            code, texte = self.verifier("chloe", "--fusion-auto")
            self.assertEqual(code, 1, texte)
            self.assertIn(attendu, texte)
        git(self.dossier, "switch", "-q", "main")

