    def test_N7_on_ne_squatte_pas_la_pr_d_un_autre(self):
        self.fermer_porte()
        self.assertEqual(self.bee("prendre", "miniz-0099", "--utilisateur", "alice")[0], 0)
        self.a("2026-10-27T12:30:00Z")
